//! Optional regenerator for `src/claude_data.rs`.
//!
//! The generated file is checked into the repo so the crate builds from a clean
//! clone without any extra setup. This command is only used by developers
//! who want to refresh the data from a newer `ai-tokenizer` release:
//!
//!   mkdir -p tmp/ai-tokenizer-pkg && cd tmp/ai-tokenizer-pkg
//!   npm pack ai-tokenizer && tar xzf ai-tokenizer-*.tgz
//!
//! Run `cargo run -p aft-tokenizer --example regenerate_claude` to regenerate.
//! When that directory (or `AFT_TOKENIZER_CLAUDE_JS`) is absent, the command
//! does nothing. Ordinary Cargo builds never run it.

use regex::Regex;
use std::env;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

fn main() {
    let manifest_dir = PathBuf::from(env::var("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let workspace_root = manifest_dir
        .parent()
        .and_then(Path::parent)
        .expect("crate should live under crates/aft-tokenizer");

    println!("cargo:rerun-if-env-changed=AFT_TOKENIZER_CLAUDE_JS");
    println!(
        "cargo:rerun-if-changed={}",
        manifest_dir.join("src/claude_data.rs").display()
    );

    let Some(source) = regeneration_source(
        workspace_root,
        env::var_os("AFT_TOKENIZER_CLAUDE_JS").map(PathBuf::from),
        &mut std::io::stdout(),
    ) else {
        return;
    };

    println!("cargo:rerun-if-changed={}", source.display());

    let js = match fs::read_to_string(&source) {
        Ok(js) => js,
        Err(err) => {
            println!(
                "cargo:warning=failed to read {}: {err}; using vendored claude_data.rs",
                source.display()
            );
            return;
        }
    };

    let string_entries = parse_string_encoder(&js);
    let binary_entries = parse_binary_encoder(&js);

    assert_eq!(
        string_entries.len(),
        64_241,
        "unexpected Claude stringEncoder entry count"
    );
    assert_eq!(
        binary_entries.len(),
        754,
        "unexpected Claude binaryEncoder entry count"
    );

    let dest = manifest_dir.join("src/claude_data.rs");

    // Build the whole file in memory, then publish it with an atomic
    // temp-in-same-dir + rename. A non-atomic in-place `File::create` here once
    // let an orphaned concurrent build truncate claude_data.rs mid-write, which
    // a later `git add` then snapshotted as a truncated source file. The
    // rename makes any reader (cargo, git) see either the old or new file whole,
    // never a partial one.
    let mut out: Vec<u8> = Vec::new();

    writeln!(
        out,
        "// Auto-generated by build.rs from ai-tokenizer Claude encoding.",
    )
    .unwrap();
    writeln!(
        out,
        "// Do not edit by hand; run `cargo build` after refreshing tmp/ai-tokenizer-pkg/."
    )
    .unwrap();
    writeln!(
        out,
        "pub static STRING_ENCODER_ENTRIES: &[(&str, u32)] = &["
    )
    .unwrap();
    for (token, rank) in &string_entries {
        writeln!(out, "    ({token:?}, {rank}),").unwrap();
    }
    writeln!(out, "];\n").unwrap();

    writeln!(
        out,
        "pub static BINARY_ENCODER_ENTRIES: &[(&[u8], u32)] = &["
    )
    .unwrap();
    for (bytes, rank) in &binary_entries {
        let bytes = bytes
            .iter()
            .map(u8::to_string)
            .collect::<Vec<_>>()
            .join(", ");
        writeln!(out, "    (&[{bytes}], {rank}),").unwrap();
    }
    writeln!(out, "];").unwrap();

    // Avoid touching the checked-in source when regeneration produces identical
    // bytes. Rewriting a Cargo input here invalidates every dependent crate and
    // turns each subsequent build into another full rebuild.
    if fs::read(&dest).is_ok_and(|current| current == out) {
        return;
    }

    // Publish atomically: write to a pid-tagged temp in the SAME directory
    // (rename is only atomic within a filesystem) then rename over dest.
    let tmp = dest.with_extension(format!("rs.tmp.{}", std::process::id()));
    fs::write(&tmp, &out).expect("write temp Claude data");
    fs::rename(&tmp, &dest).expect("atomically publish Claude data");

    println!(
        "cargo:warning=regenerated {} from {}",
        dest.display(),
        source.display()
    );
}

fn regeneration_source(
    workspace_root: &Path,
    explicit: Option<PathBuf>,
    out: &mut impl Write,
) -> Option<PathBuf> {
    let input = explicit
        .clone()
        .unwrap_or_else(|| workspace_root.join("tmp/ai-tokenizer-pkg/package/dist/encoding"));
    if let Some(watched_path) = existing_watch_path(workspace_root, &input) {
        writeln!(out, "cargo:rerun-if-changed={}", watched_path.display()).unwrap();
    }
    match explicit {
        Some(path) if path.exists() => Some(path),
        Some(path) => {
            writeln!(out, "cargo:warning=AFT_TOKENIZER_CLAUDE_JS={} does not exist; using vendored claude_data.rs", path.display()).unwrap();
            None
        }
        None => locate_default_source(workspace_root),
    }
}

fn existing_watch_path(workspace_root: &Path, input: &Path) -> Option<PathBuf> {
    if input.exists() {
        return Some(input.to_path_buf());
    }
    // Cargo treats missing watched paths as dirty on every build. Watching the
    // nearest existing directory detects a new source without constant rebuilds.
    let mut candidate = input.parent()?;
    while candidate != workspace_root {
        if !candidate.starts_with(workspace_root) {
            return None;
        }
        if candidate.is_dir() {
            return Some(candidate.to_path_buf());
        }
        candidate = candidate.parent()?;
    }
    None
}

fn locate_default_source(workspace_root: &Path) -> Option<PathBuf> {
    let encoding_dir = workspace_root.join("tmp/ai-tokenizer-pkg/package/dist/encoding");
    let entries = fs::read_dir(&encoding_dir).ok()?;

    for entry in entries.flatten() {
        let path = entry.path();
        let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if name.starts_with("claude-") && name.ends_with(".js") {
            return Some(path);
        }
    }
    None
}

fn parse_string_encoder(js: &str) -> Vec<(String, u32)> {
    let start = js
        .find("const stringEncoder = {")
        .expect("stringEncoder start");
    let after_start = &js[start..];
    let block_start = after_start.find('{').expect("stringEncoder open brace") + 1;
    let block_end = after_start
        .find("\n};\nconst binaryEncoder")
        .expect("stringEncoder closing brace");
    let block = &after_start[block_start..block_end];

    let mut entries = Vec::new();
    for line in block.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let line = line.strip_suffix(',').unwrap_or(line).trim();
        let (key, rest) = if line.starts_with('"') {
            let (key, consumed) = parse_js_string_literal(line);
            let rest = line[consumed..]
                .trim_start()
                .strip_prefix(':')
                .expect("quoted stringEncoder key should be followed by colon");
            (key, rest)
        } else {
            let (key, rest) = line
                .split_once(':')
                .expect("unquoted stringEncoder key/value");
            (key.trim().to_owned(), rest)
        };
        let rank = parse_js_u32(rest.trim());
        entries.push((key, rank));
    }

    entries
}

fn parse_binary_encoder(js: &str) -> Vec<(Vec<u8>, u32)> {
    let start = js
        .find("const binaryEncoder = [")
        .expect("binaryEncoder start");
    let after_start = &js[start..];
    let end = after_start
        .find("\n];\nconst decoder")
        .expect("binaryEncoder end");
    let block = &after_start[..end];

    let entry_re = Regex::new(
        r"(?s)\[\s*new Uint8Array\(\s*\[([0-9,\s]+)\]\s*\)\s*,\s*([0-9]+(?:e[0-9]+)?)\s*\]",
    )
    .expect("binaryEncoder regex");

    entry_re
        .captures_iter(block)
        .map(|caps| {
            let bytes = caps[1]
                .split(',')
                .map(str::trim)
                .filter(|part| !part.is_empty())
                .map(|part| part.parse::<u8>().expect("binaryEncoder byte"))
                .collect::<Vec<_>>();
            let rank = parse_js_u32(&caps[2]);
            (bytes, rank)
        })
        .collect()
}

fn parse_js_u32(input: &str) -> u32 {
    if let Ok(value) = input.parse::<u32>() {
        return value;
    }

    let value = input
        .parse::<f64>()
        .unwrap_or_else(|err| panic!("invalid JS numeric literal {input:?}: {err}"));
    assert!(
        value.is_finite() && value.fract() == 0.0 && value >= 0.0 && value <= u32::MAX as f64,
        "JS numeric literal is not a u32: {input:?}"
    );
    value as u32
}

fn parse_js_string_literal(input: &str) -> (String, usize) {
    let mut chars = input.char_indices().peekable();
    assert_eq!(chars.next().map(|(_, ch)| ch), Some('"'));

    let mut output = String::new();
    while let Some((idx, ch)) = chars.next() {
        match ch {
            '"' => return (output, idx + ch.len_utf8()),
            '\\' => {
                let (_, escaped) = chars.next().expect("unterminated JS string escape");
                match escaped {
                    '"' => output.push('"'),
                    '\\' => output.push('\\'),
                    '/' => output.push('/'),
                    'b' => output.push('\u{0008}'),
                    'f' => output.push('\u{000c}'),
                    'n' => output.push('\n'),
                    'r' => output.push('\r'),
                    't' => output.push('\t'),
                    'v' => output.push('\u{000b}'),
                    '0' => output.push('\0'),
                    'x' => {
                        let high = chars.next().expect("missing first hex escape digit").1;
                        let low = chars.next().expect("missing second hex escape digit").1;
                        let value = hex_value(high) * 16 + hex_value(low);
                        output.push(char::from_u32(value).expect("valid hex escape"));
                    }
                    'u' => {
                        let mut value = 0_u32;
                        if chars.peek().is_some_and(|(_, ch)| *ch == '{') {
                            chars.next();
                            let mut digits = 0;
                            loop {
                                let digit = chars.next().expect("unterminated unicode escape").1;
                                if digit == '}' {
                                    assert!(digits > 0, "empty unicode escape");
                                    break;
                                }
                                digits += 1;
                                value = value
                                    .checked_mul(16)
                                    .and_then(|value| value.checked_add(hex_value(digit)))
                                    .expect("unicode escape too large");
                            }
                        } else {
                            for _ in 0..4 {
                                let digit = chars.next().expect("missing unicode escape digit").1;
                                value = value * 16 + hex_value(digit);
                            }
                            if (0xD800..=0xDBFF).contains(&value) {
                                assert_eq!(chars.next().map(|(_, ch)| ch), Some('\\'));
                                assert_eq!(chars.next().map(|(_, ch)| ch), Some('u'));
                                let mut low = 0;
                                for _ in 0..4 {
                                    let digit =
                                        chars.next().expect("missing low surrogate digit").1;
                                    low = low * 16 + hex_value(digit);
                                }
                                assert!((0xDC00..=0xDFFF).contains(&low), "invalid low surrogate");
                                value = 0x10000 + ((value - 0xD800) << 10) + (low - 0xDC00);
                            }
                        }
                        output.push(char::from_u32(value).expect("valid unicode escape"));
                    }
                    other => panic!("unsupported JS string escape: \\{other}"),
                }
            }
            other => output.push(other),
        }
    }

    panic!("unterminated JS string literal")
}

fn hex_value(ch: char) -> u32 {
    ch.to_digit(16)
        .unwrap_or_else(|| panic!("invalid hex escape digit: {ch}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn absent_regeneration_source_is_watched() {
        let root = std::env::temp_dir().join(format!("aft-tokenizer-watch-{}", std::process::id()));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        let mut out = Vec::new();
        assert!(regeneration_source(&root, None, &mut out).is_none());
        assert!(String::from_utf8(out).unwrap().is_empty());

        fs::create_dir_all(root.join("tmp")).unwrap();
        let mut out = Vec::new();
        assert!(regeneration_source(&root, None, &mut out).is_none());
        assert_eq!(
            String::from_utf8(out).unwrap(),
            format!("cargo:rerun-if-changed={}\n", root.join("tmp").display())
        );
        let encoding = root.join("tmp/ai-tokenizer-pkg/package/dist/encoding");
        fs::create_dir_all(&encoding).unwrap();
        let source = encoding.join("claude-new.js");
        fs::write(&source, "").unwrap();
        let mut out = Vec::new();
        assert_eq!(regeneration_source(&root, None, &mut out), Some(source));
        assert_eq!(
            String::from_utf8(out).unwrap(),
            format!("cargo:rerun-if-changed={}\n", encoding.display())
        );
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn js_invalid_unicode_escape_is_rejected() {
        for input in [
            r#""\uD83D\u0041""#,
            r#""\uDE00""#,
            r#""\u{}""#,
            r#""\u{110000}""#,
        ] {
            assert!(std::panic::catch_unwind(|| parse_js_string_literal(input)).is_err());
        }
    }

    #[test]
    fn js_unicode_surrogates_decode_as_one_scalar() {
        assert_eq!(
            parse_js_string_literal(r#""\uD83D\uDE00"tail"#),
            ("😀".into(), 14)
        );
    }

    #[test]
    fn js_braced_unicode_escape_decodes_as_one_scalar() {
        assert_eq!(
            parse_js_string_literal(r#""\u{0001F600}""#),
            ("😀".into(), 14)
        );
        assert_eq!(
            parse_js_string_literal(r#""\u{1F600}"tail"#),
            ("😀".into(), 11)
        );
    }

    #[test]
    fn js_existing_escapes_and_raw_utf8_are_preserved() {
        assert_eq!(
            parse_js_string_literal(r#""é\u2014\x41"tail"#),
            ("é—A".into(), 14)
        );
    }
}
